    result = []
    for number in numbers:
        chunk = [number & 0x7F]
        number >>= 7
        while number:
            chunk.append((number & 0x7F) | 0x80)
            number >>= 7
        result.extend(reversed(chunk))
    return result


def decode(bytes_):
    values = []
    current = 0
    complete = True
    for byte in bytes_:
        current = (current << 7) | (byte & 0x7F)
        if byte & 0x80:
            complete = False
        else:
            values.append(current)
            current = 0
            complete = True
    if not complete:
        raise ValueError("incomplete sequence")
    return values
